def src(label,url):return dict(title=label,url=url,checked=CHECKED)
def ref(label,url):return dict(label=label,url=url)
def E(ident,title,iso,url,start='',end='',**fields):
    country={'AND':T('Андорра','Andorra'),'MDA':T('Республика Молдова','República de Moldavia')}[iso]
    e=event(ident,title,country,url,start,end,**fields)
    e.update(country=country,region=T('Европа','Europa'),iso=[iso],checked=CHECKED)
    for key,value in dict(entry=GATE,action=GATE,language=LANG,language_certainty=LANG,cost=UNKNOWN,reward=AWARD,note=AWARD,level=T('B — национальный / региональный маршрут','B — ruta nacional / regional')).items():
        if key not in fields:e[key]=value
    return e
def fit(lo,hi,grade=False):
    out={}
    for child,ages in [('matvey',(9,10)),('oscar',(6,7))]:
        status='not_eligible'if min(ages)>hi else'later'if max(ages)<lo else'conditional'
        detail=GATE
        if status=='later':detail=T('В течение 2027 ребёнок ещё младше опубликованного минимума.', 'Durante 2027 el niño aún menor del mínimo publicado.')
        elif status=='not_eligible':detail=T('Ребёнок уже старше верхней границы этого младшего потока.', 'Niño ya mayor del límite superior de este grupo menor.')
        elif min(ages)<lo or max(ages)>hi:detail=T('В 2027 возраст пересекает границу: точная дата рождения и начало смены обязательны.', 'En 2027 edad cruza un límite: fecha exacta de nacimiento e inicio del turno obligatorios.')+' '+GATE
        if grade:detail+=' '+T('Числовой возраст не заменяет обязательный школьный класс.', 'Edad numérica no sustituye curso escolar obligatorio.')
        out[child]=candidate(status,detail)
    return out
def P(i,slug,name,iso,age,themes,lo,hi,formats=('day',)):
    p=base('CP'+str(i),slug,name,iso,T('Андорра','Andorra')if iso=='AND'else T('Республика Молдова','República de Moldavia'),'Andorra'if iso=='AND'else'Chișinău',themes)
    p.update(age=age,formats=list(formats),language=LANG,confirmed_instruction_languages=[],language_evidence_role='unconfirmed',checked=CHECKED,family_fit=fit(lo,hi),questions=[GATE],editorial_reason=AWARD,shortlist=[])
    p['timing'].update(status='next_unannounced',label=UNKNOWN,sessions=[],session_details=[],variant_keyed=True)
    p['price'].update(amount=None,currency='EUR'if iso=='AND'else'MDL',year=2026,unit='programme',label=UNKNOWN,extras=TRIP,deposit=UNKNOWN)
    return p

